from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data.get('events', [])):
        if event.get('sequence', 0) > cutoff:
            continue
        if 'id' in event:
            key = ('id', event['id'])
        else:
            key = ('anonymous', position)
        revision = event.get('revision', 0)
        previous = winners.get(key)
        if previous is None or (revision, position) >= (previous[0], previous[1]):
            winners[key] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in winners.values():
        if event.get('void', False):
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances.setdefault(key, 0)
        balances[key] += amount(event, data.get('rounding', 'floor'))

    return {'balances': balances}

def _round_basis_points(numerator, mode):
    if mode == 'half_up':
        return (numerator + 5000) // 10000
    return numerator // 10000


def amount(event, mode):
    gross = event['price'] * event.get('quantity', 1)
    discount = max(0, min(10000, event.get('discount_bp', 0)))
    net = _round_basis_points(gross * (10000 - discount), mode)
    tax = _round_basis_points(net * event.get('tax_bp', 0), mode)
    total = net + tax
    if event.get('kind') == 'refund':
        return -total
    return total
